import { getEnv } from "../platform/compat/process.js";
import { CONFIG_VALIDATION_ERROR } from "../errors/index.js";
import { createRemoteMCPToolSource } from "./remote-mcp.js";
const DEFAULT_ENDPOINT = "https://mcp.context7.com/mcp";
function resolveApiKey(config) {
    const key = config.apiKey ?? getEnv("CONTEXT7_API_KEY");
    if (!key) {
        throw CONFIG_VALIDATION_ERROR.create({
            detail: "Context7 API key is required. Pass apiKey or set the CONTEXT7_API_KEY environment variable.",
        });
    }
    return key;
}
/** Create context7 tool source. */
export function createContext7ToolSource(config = {}) {
    return createRemoteMCPToolSource({
        id: "context7",
        endpoint: config.endpoint ?? DEFAULT_ENDPOINT,
        headers: () => ({
            CONTEXT7_API_KEY: resolveApiKey(config),
        }),
    });
}
